    return 0.6 * current_reputation + 0.4 * new_score

def decide(recipient_reputation, round_num, my_history):
    # Base threshold becomes stricter over time (positive slope)
    base_threshold = 0.01 * round_num - 0.5

    # Look at last 5 actions for streak analysis
    recent_window = 5
    recent = my_history[-recent_window:] if len(my_history) >= recent_window else my_history
    if len(recent) >= 5:
        cooperations = sum(1 for action in recent if action)  # True = cooperate
        if cooperations >= 4:
            # Many cooperations -> more forgiving
            threshold = base_threshold - 0.2
        elif cooperations <= 1:
            # Many defections -> stricter
            threshold = base_threshold + 0.3
        else:
            threshold = base_threshold
    else:
        threshold = base_threshold

    return recipient_reputation > threshold

def evaluate(current_reputation, observation, my_history, round_num):
    # Use a stronger update weight (0.7) and slightly asymmetric scores
    alpha = 0.7
    if observation['action'] == 'cooperate':
        new_score = 0.85
    else:
        new_score = -0.95
    return (1 - alpha) * current_reputation + alpha * new_score

def decide(recipient_reputation, round_num, my_history):
    # Base threshold starts positive and becomes more negative over rounds
    base = 0.1 - 0.02 * round_num

    # Look at own recent cooperation over a shorter window (10)
    window = 10
    recent = my_history[-window:] if len(my_history) >= window else my_history
    if len(recent) >= 1:
        coop_rate = sum(1 for a in recent if a) / len(recent)
        # Adjust threshold based on own behavior
        if coop_rate > 0.8:
